// ---- assembly ----
function build() {
  const uses = Object.create(null);
  const push = (id, row) => { (uses[id] || (uses[id] = [])).push(Object.freeze(row)); };
  for (const src of [LIVE, LIVE_EXTRA]) {
    for (const id of Object.keys(src)) {
      for (const [by, role, what, cite] of src[id]) {
        push(id, { by, role, live: true, why: 'Live today: ' + what + '.', cite });
      }
    }
  }
  for (const by of Object.keys(PROPOSED)) {
    for (const [id, role, why] of PROPOSED[by]) {
      // A phantom can never become a need, not even by a typo in the table above.
      if (PHANTOMS.includes(id)) continue;
      push(id, { by, role, live: false, why });
    }
  }
  for (const id of Object.keys(uses)) Object.freeze(uses[id]);
  return Object.freeze(uses);
}

/** USES[resId] -> [{by, role, live, why, cite?}]. live rows first, then proposed. */
export const USES = build();

/** Every id this file was built against (the 420-id union at generation time). */
export const KNOWN_IDS = Object.freeze(ALL_IDS.slice());

const BY_NODE = (() => {
  const m = Object.create(null);
  for (const id of Object.keys(USES)) {
    // Several live edges can say the same thing (four Weapon Smith recipes all take cloth). A view wants
    // ONE need per (node, id, role, live) with every cite attached, not four look-alike lines.
    const seen = Object.create(null);
    for (const u of USES[id]) {
      if (u.role === 'sim') continue;
      const k = u.by + '|' + u.role + '|' + u.live;
      if (seen[k]) { if (u.cite) seen[k].cite = seen[k].cite ? seen[k].cite + ' ; ' + u.cite : u.cite; continue; }
      const row = { id, role: u.role, live: u.live, why: u.why, cite: u.cite };
      seen[k] = row; (m[u.by] || (m[u.by] = [])).push(row);
    }
  }
  return m;
})();

/**
 * What a node needs. One entry per (id, role); live entries first so a view that truncates the list
 * shows the true facts before the wishes. 'sim' rows are never needs (see header).
 */
export function needsOf(nodeId) {
  const rows = (BY_NODE[nodeId] || []).slice();
  rows.sort((a, b) => (a.live === b.live ? 0 : a.live ? -1 : 1));
  return rows;
}

function ids(catalog) {
  if (!catalog) return KNOWN_IDS;
  const arr = Array.isArray(catalog) ? catalog : (catalog.CATALOG || catalog.rows || Object.values(catalog));
  return arr.map((r) => (typeof r === 'string' ? r : r && r.id)).filter(Boolean);
}

/**
 * The subset of needsOf() that a player can get by FIGHTING. De-duplicated by id.
 * `lootable` is injected by the caller: a one-argument test (loot.js lootableWith(catalog) — NOT bare
 * isLootable, which needs the catalogue), a catalogue / row array whose rows carry handLoot, or an id list;
 * because coverage.js may not import a same-wave sibling. The built-in hand-loot list is only the
 * fallback. It is deliberately the 153 hand-authored drops, not all 410 SALVAGE ids: the uniform
 * salvage roll can technically produce anything, and "you might get it one time in 410" is not a plan.
 */
export function lootNeedsOf(nodeId, lootable) {
  let test = (id) => HAND_LOOT.has(id);
  if (typeof lootable === 'function') test = lootable;
  else if (lootable) {
    const set = new Set();
    const rows = Array.isArray(lootable) ? lootable : (typeof lootable.all === 'function' ? lootable.all() : Object.values(lootable));
    // catalog.js rows carry BOTH flags. inLoot is true for 409 of 420 ids (the uniform salvage roll), so
    // accepting it whenever handLoot is also on offer made every need look battle-lootable and the
    // per-business minimum meaningless. handLoot wins; inLoot only counts for a catalogue without it.
    const hasHand = rows.some((r) => r && typeof r === 'object' && 'handLoot' in r);
    for (const r of rows) {
      if (typeof r === 'string') set.add(r); else if (r && (hasHand ? r.handLoot : r.inLoot)) set.add(r.id);
    }
    if (set.size) test = (id) => set.has(id);
  }
  const seen = new Set(); const out = [];
  for (const n of needsOf(nodeId)) {
    if (seen.has(n.id) || !test(n.id)) continue;
    seen.add(n.id); out.push(n);
  }
  return out;
}

/**
 * How much of a node's needs list is true in the shipped game. Counts only, no economy numbers.
 * The modal prints this beside the list so a PROPOSED need is never read as a real requirement.
 */
export function liveSummary(nodeId, lootable) {
  const needs = needsOf(nodeId); const loot = lootNeedsOf(nodeId, lootable);
  const uniq = (rows) => new Set(rows.map((r) => r.id)).size;
  return {
    needs: uniq(needs), live: uniq(needs.filter((n) => n.live)), proposed: uniq(needs.filter((n) => !n.live)),
    lootNeeds: loot.length, lootLive: loot.filter((n) => n.live).length,
  };
}

/** Catalogue ids with no use at all (not even a sim edge). The bar is an empty array. */
export function uncovered(catalog) {
  return ids(catalog).filter((id) => !USES[id] || USES[id].length === 0);
}

/** Ids whose ONLY uses are simulated-city edges: covered on paper, useless in a player's hands. */
export function simOnly(catalog) {
  return ids(catalog).filter((id) => USES[id] && USES[id].length && USES[id].every((u) => u.role === 'sim'));
}

/** Rows that point at an id the catalogue does not have, or at a phantom. graph.js reports these. */
export function strays(catalog) {
  const known = new Set(ids(catalog));
  return Object.keys(USES).filter((id) => !known.has(id) || PHANTOMS.includes(id));
}

/** Share of all PROPOSED rows per node: the no-dumping-ground check the audit pins. */
export function proposedShare() {
  const n = Object.create(null); let total = 0;
  for (const by of Object.keys(PROPOSED)) { n[by] = PROPOSED[by].length; total += n[by]; }
  const out = Object.create(null);
  for (const by of Object.keys(n)) out[by] = { rows: n[by], share: total ? n[by] / total : 0 };
  return { total, byNode: out };
}
